<template><StatePanel v-if="pending" kind="loading" title="Loading checkout" message="Preparing the checkout form." /><StatePanel v-else-if="error || !identity" kind="error" title="Checkout unavailable" message="This storefront could not be loaded." /><StorefrontFrame v-else :identity="identity" :navigation="navigation" :base="base"><PageHeader title="Checkout" description="Your order is created from server-calculated prices. Online payment is confirmed only by a signed provider webhook." /><StatePanel v-if="!cart.cart?.items?.length" class="mt-8" title="Nothing to check out" message="Return to the shop and add an item first."><ButtonLink :to="`${base}/shop`">Browse shop</ButtonLink></StatePanel><form v-else class="mt-8 grid gap-10 lg:grid-cols-[minmax(0,1fr)_22rem]" @submit.prevent="submit"><div class="space-y-8"><fieldset class="grid gap-5 border-y bg-card p-5 sm:grid-cols-2"><legend class="px-2 font-bold">Contact details</legend><div><label class="field-label" for="checkout-first">First name</label><Input id="checkout-first" v-model.trim="form.first_name" required /></div><div><label class="field-label" for="checkout-last">Last name</label><Input id="checkout-last" v-model.trim="form.last_name" required /></div><div><label class="field-label" for="checkout-email">Email</label><Input id="checkout-email" v-model.trim="form.email" type="email" required /></div><div><label class="field-label" for="checkout-phone">Phone</label><Input id="checkout-phone" v-model.trim="form.phone" inputmode="tel" /></div></fieldset><fieldset class="grid gap-5 border-y bg-card p-5 sm:grid-cols-2"><legend class="px-2 font-bold">Fulfillment</legend><div><label class="field-label" for="fulfillment">Method</label><NativeSelect id="fulfillment" v-model="form.fulfillment_type"><option value="delivery">Delivery</option><option value="pickup">Pickup</option><option value="digital">Digital delivery</option></NativeSelect></div><div v-if="form.fulfillment_type === 'delivery'"><label class="field-label" for="shipping-zone">Shipping zone</label><NativeSelect id="shipping-zone" v-model="form.shipping_zone_public_id" required><option disabled value="">Choose a zone</option><option v-for="zone in zones" :key="zone.public_id" :value="zone.public_id">{{ zone.name }} — {{ money(zone.flat_rate) }}</option></NativeSelect></div><template v-if="form.fulfillment_type === 'delivery'"><div class="sm:col-span-2"><label class="field-label" for="address-line">Street address</label><Input id="address-line" v-model.trim="form.shipping_address.line1" required /></div><div><label class="field-label" for="address-city">City</label><Input id="address-city" v-model.trim="form.shipping_address.city" required /></div><div><label class="field-label" for="address-region">Region</label><Input id="address-region" v-model.trim="form.shipping_address.region" required /></div></template></fieldset><fieldset class="border-y bg-card p-5"><legend class="px-2 font-bold">Payment</legend><label v-for="method in paymentMethods" :key="method.value" class="flex items-start gap-3 border-b py-4 last:border-b-0"><NativeRadio v-model="form.payment_method" :value="method.value" class="mt-1" /><span><span class="block font-semibold">{{ method.label }}</span><span class="mt-1 block text-sm text-muted-foreground">{{ method.description }}</span></span></label></fieldset></div><aside class="border-t pt-6 lg:border-l lg:border-t-0 lg:pl-8 lg:pt-0"><h2 class="font-bold">Order total</h2><p class="mt-4 text-3xl font-bold">{{ money(cart.cart.totals.grand_total + selectedShippingRate) }}</p><p class="mt-2 text-xs leading-5 text-muted-foreground">Final total is recalculated on the server from the selected shipping zone.</p><p v-if="message" :class="messageTone" class="mt-5 text-sm" aria-live="polite">{{ message }}</p><Button class="mt-6 w-full" :disabled="submitting">{{ submitting ? 'Placing order…' : 'Place order' }}</Button></aside></form></StorefrontFrame></template>
<script setup>
definePageMeta({ layout: 'storefront' }); const route = useRoute(); const { identity, navigation, pending, error, baseURL, siteBase: base } = useStorefrontContext(route.params.slug); const cart = useCartStore(); const zones = ref([]); const submitting = ref(false); const message = ref(''); const messageTone = ref('text-muted-foreground'); const form = reactive({ email: '', first_name: '', last_name: '', phone: '', fulfillment_type: 'delivery', shipping_zone_public_id: '', shipping_address: { line1: '', city: '', region: '', country: 'PH' }, payment_method: 'paymongo' }); const paymentMethods = [{ value: 'paymongo', label: 'Online payment', description: 'Continue to the merchant’s PayMongo checkout for enabled methods such as QR Ph, GCash, Maya, or cards.' }, { value: 'cod', label: 'Cash on delivery', description: 'Pay when the delivery is received, if supported by the business.' }, { value: 'manual', label: 'Bank or manual payment', description: 'Place the order and follow the business’s payment instructions.' }]; const selectedShippingRate = computed(() => Number(zones.value.find((zone) => zone.public_id === form.shipping_zone_public_id)?.flat_rate || 0)); onMounted(async () => { await cart.load(route.params.slug); zones.value = await $fetch(`public/${route.params.slug}/shipping-zones/`, { baseURL }).catch(() => []) }); watch(() => form.fulfillment_type, (value) => { if (value !== 'delivery') form.shipping_zone_public_id = '' }); const money = (value) => new Intl.NumberFormat('en-PH', { style: 'currency', currency: identity.value?.currency || 'PHP' }).format(Number(value || 0)); async function submit() { submitting.value = true; message.value = ''; try { const payload = { ...form, success_url: `${window.location.origin}${base}/order/return`, cancel_url: `${window.location.origin}${base}/checkout?status=cancelled` }; if (form.fulfillment_type !== 'delivery') { delete payload.shipping_zone_public_id; delete payload.shipping_address } const order = await cart.checkout(payload); localStorage.setItem(`pixelcore-pending-order:${route.params.slug}`, order.public_id); if (order.checkout_url) { window.location.assign(order.checkout_url); return } await navigateTo(`${base}/order/${order.public_id}`) } catch (requestError) { message.value = requestError?.data?.error?.message || 'Checkout could not be completed. Review the order and try again.'; messageTone.value = 'text-destructive' } finally { submitting.value = false } }
</script>
